# owner: platform
"""Lay students out in rows for a seating chart."""

from typing import List
from rosterkit.models import Student
from operator import attrgetter


def seating_rows(
    students: List[Student], per_row: int
) -> List[str]:
    """One line per row, students sorted by last name."""
    check_seating(students, per_row)
    ordered = sorted(students, key=attrgetter("last_name"))
    return format_rows(ordered, per_row)


def check_seating(
    students: List[Student], per_row: int
) -> None:
    if per_row <= 0:
        raise ValueError("seats per row must be positive")
    if not students:
        raise ValueError("no students to seat")


def format_rows(
    ordered: List[Student], per_row: int
) -> List[str]:
    starts = range(0, len(ordered), per_row)
    return [
        format_row(number, ordered[start:start + per_row])
        for number, start in enumerate(starts, 1)
    ]


def format_row(number: int, group: List[Student]) -> str:
    names = " | ".join(item.display_name for item in group)
    return f"Row {number}: {names}"

