# owner: platform
import unittest
from rosterkit.seating import seating_rows
from rosterkit.models import Student


def make_student(last_name, first_name):
    return Student(first_name, last_name, first_name, "A")


class SeatingRowsTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            make_student("Halloway", "Juno"),
            make_student("Dunmere", "Piet"),
            make_student("Varrow", "Ines")
        ]

    def test_rows_hold_students_in_last_name_order(self):
        expected = [
            "Row 1: Dunmere, Piet | Halloway, Juno",
            "Row 2: Varrow, Ines"
        ]
        rows = seating_rows(self.students, 2)
        self.assertEqual(rows, expected)

    def test_zero_seats_per_row_raises(self):
        with self.assertRaises(ValueError):
            seating_rows(self.students, 0)

    def test_negative_seats_per_row_raises(self):
        with self.assertRaises(ValueError):
            seating_rows(self.students, -1)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 2)
